const item = $input.first().json;

// WAHA envia em dois formatos possíveis:
// Formato 1: { event: 'message', payload: { from, body, notifyName, fromMe } }
// Formato 2: { from, body, notifyName } (direto, sem payload aninhado)
const payload = item.payload || item;

const chatId = payload.from || payload.chatId || '';
const mensagem = payload.body || payload.text || payload.mensagem || '';
const nome = payload.notifyName || payload._data?.notifyName || chatId.replace(/@[\w.]+$/, '');

// Ignorar grupos, mensagens de si mesmo ou vazias
if (!mensagem || !chatId || chatId.includes('@g.us') || payload.fromMe === true) {
  return [];
}

return [{ json: { chatId, mensagem, nome } }];

const redisResult = $input.first().json;
const extracao = $('Extrair Mensagem').first().json;

let historico = [];
try {
  if (redisResult.value) {
    const parsed = JSON.parse(redisResult.value);
    historico = Array.isArray(parsed) ? parsed : [];
  }
} catch {
  historico = [];
}

// Manter últimas 20 mensagens para não estourar contexto do Gemini
if (historico.length > 20) {
  historico = historico.slice(-20);
}

return [{
  json: {
    chatId: extracao.chatId,
    mensagem: extracao.mensagem,
    nome: extracao.nome,
    historico
  }
}];

