const geminiData = $input.first().json;
const { chatId, mensagem } = $('Extrair Mensagem').first().json;

// Extrair texto da resposta do Gemini
let textoCompleto = '';
try {
  textoCompleto = geminiData.candidates[0].content.parts[0].text || '';
} catch {
  textoCompleto = 'Desculpe, não consegui processar sua mensagem. Pode repetir?';
}

let tipo = 'conversa';
let textoResposta = textoCompleto;
let dadosReserva = null;

// Detectar solicitação de atendente humano
if (textoCompleto.includes('ATENDENTE_HUMANO')) {
  tipo = 'humano';
  textoResposta = textoCompleto
    .replace(/ATENDENTE_HUMANO(?::\{[^}]*\})?/g, '')
    .trim();
  if (!textoResposta) {
    textoResposta = 'Entendido! Vou te conectar com um de nossos atendentes agora. Aguarde um momento! 😊';
  }
}

// Detectar criação de reserva (não sobrescreve se já for humano)
if (tipo !== 'humano' && textoCompleto.includes('RESERVA_JSON:')) {
  tipo = 'reserva';
  const match = textoCompleto.match(/RESERVA_JSON:(\{[^}]+\})/);
  if (match) {
    try { dadosReserva = JSON.parse(match[1]); } catch { }
  }
  textoResposta = textoCompleto.replace(/RESERVA_JSON:\{[^}]+\}/g, '').trim();
  if (!textoResposta) {
    textoResposta = 'Perfeito! Registrei sua reserva com sucesso. Em breve você receberá a confirmação! 🎉';
  }
}

return [{ json: { chatId, mensagem, textoResposta, tipo, dadosReserva } }];

